  const lift = (28 - (opp.grabTimer || 0)) * 3, [dx, dy] = tipOf('leg', 0)
  part(c, f, 'leg', 0, ctrX(opp) - dx * (f.facing || 1), opp.y + 26 - dy - lift * 0.2, { flip: f.facing || 1 })
